import{_ as r,o as t,c as o,a5 as e}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"715-批量文件夹名、文件名处理工具","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["文件夹文件名处理工具","文件夹重命名","文件重命名工具"]},"headers":[],"relativePath":"md/文件及文件夹批处理/715-批量文件夹名、文件名处理工具.md","filePath":"md/文件及文件夹批处理/715-批量文件夹名、文件名处理工具.md"}'),p={name:"md/文件及文件夹批处理/715-批量文件夹名、文件名处理工具.md"};function n(h,a,s,i,l,d){return t(),o("div",null,[...a[0]||(a[0]=[e('<h3 id="批量文件、文件夹名重命名工具" tabindex="-1">批量文件、文件夹名重命名工具 <a class="header-anchor" href="#批量文件、文件夹名重命名工具" aria-label="Permalink to &quot;批量文件、文件夹名重命名工具&quot;">​</a></h3><p>批量文件、文件夹名处理工具，高效地对文件和文件夹进行批量重命名操作。</p><p>程序提供灵活的重命名规则，支持子文件夹穿透、拖放操作以及结果导出功能。</p><p>【1】、支持的文件格式：所有格式</p><p>【2】、是否支持子文件夹穿透：支持，**子文件夹穿透：**支持递归处理指定文件夹内的所有文件和子文件夹,<strong>勾选选项即可实现。</strong></p><p>**路径输入与拖放支持：**用户可手动输入文件/文件夹路径，或通过拖放方式快速导入多个路径。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250924130941175869058147624.jpg" alt=""></p><h3 id="灵活的重命名规则" tabindex="-1">灵活的重命名规则： <a class="header-anchor" href="#灵活的重命名规则" aria-label="Permalink to &quot;灵活的重命名规则：&quot;">​</a></h3><p>1、删除文件名左侧或右侧指定数量的字符。</p><p>2、删除指定分隔符前后的内容（可选择第几次出现的分隔符）。</p><p>3、在文件名首尾添加自定义前缀或后缀。</p><h3 id="预览功能" tabindex="-1">预览功能： <a class="header-anchor" href="#预览功能" aria-label="Permalink to &quot;预览功能：&quot;">​</a></h3><p>在执行重命名前，显示原文件名和新文件名的对比，允许用户检查重命名效果。</p><h3 id="批量删除列表项" tabindex="-1">批量删除列表项： <a class="header-anchor" href="#批量删除列表项" aria-label="Permalink to &quot;批量删除列表项：&quot;">​</a></h3><p>支持通过右键菜单或按钮删除选中的文件/文件夹项。</p><h3 id="日志记录" tabindex="-1">日志记录： <a class="header-anchor" href="#日志记录" aria-label="Permalink to &quot;日志记录：&quot;">​</a></h3><p>记录操作过程，包含时间戳，便于跟踪操作历史。</p><h3 id="导出功能" tabindex="-1">导出功能： <a class="header-anchor" href="#导出功能" aria-label="Permalink to &quot;导出功能：&quot;">​</a></h3><p>导出原文件名列表到 XLSX 文件。</p><p>导出重命名后的新文件名列表到 XLSX 文件（可选）。</p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><h3 id="实例-1-批量删除文件名中的前缀" tabindex="-1">实例 1：批量删除文件名中的前缀 <a class="header-anchor" href="#实例-1-批量删除文件名中的前缀" aria-label="Permalink to &quot;实例 1：批量删除文件名中的前缀&quot;">​</a></h3><p>场景：有一个文件夹，内含文件如 backup_data_001.txt、backup_data_002.txt，希望删除文件名中的 backup_ 前缀。</p><h3 id="操作步骤" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h3><p>拖放文件夹到程序的路径输入框，或手动输入文件夹路径。</p><p>勾选“启用子文件夹穿透”（若需要处理子文件夹）。</p><p>在“删除指定字符前内容”设置：</p><p>指定字符：_</p><p>第几次出现：1</p><p>勾选“启用”。</p><p>点击“手动预览”，查看新文件名（如 data_001.txt、data_002.txt）。</p><p>确认无误后，点击“执行重命名”完成操作。</p><p>可勾选“导出新文件名到 XLSX”将结果保存为 Excel 文件。</p><p>结果：所有文件的 backup_ 前缀被移除，生成新文件名。</p><h3 id="实例-2-为文件名添加编号后缀" tabindex="-1">实例 2：为文件名添加编号后缀 <a class="header-anchor" href="#实例-2-为文件名添加编号后缀" aria-label="Permalink to &quot;实例 2：为文件名添加编号后缀&quot;">​</a></h3><p>场景：用户需要为文件夹中的图片文件（如 photo.jpg、image.png）添加统一后缀 _2025。</p><h3 id="操作步骤-1" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤-1" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h3><p>拖放图片文件夹到路径输入框。</p><p>在“右侧添加内容（添加后缀）”设置：</p><p>输入 _2025。</p><p>勾选“启用”。</p><p>点击“手动预览”，确认新文件名（如 photo_2025.jpg、image_2025.png）。</p><p>点击“执行重命名”完成操作。</p><p>可选择导出原文件名和新文件名到 XLSX 文件。</p><p>结果：所有图片文件名后添加 _2025 后缀。</p><h3 id="实例-3-清理文件名中的无效字符" tabindex="-1">实例 3：清理文件名中的无效字符 <a class="header-anchor" href="#实例-3-清理文件名中的无效字符" aria-label="Permalink to &quot;实例 3：清理文件名中的无效字符&quot;">​</a></h3><p>场景：用户有一个文件夹，文件名为 doc_001_temp_final.docx、doc_002_temp_final.docx，希望删除 _temp_final 部分。</p><h3 id="操作步骤-2" tabindex="-1">操作步骤： <a class="header-anchor" href="#操作步骤-2" aria-label="Permalink to &quot;操作步骤：&quot;">​</a></h3><p>输入或拖放文件夹路径。</p><p>在“删除指定字符后内容（从右向左数）”设置：</p><p>指定字符：_</p><p>第几次出现：2</p><p>勾选“启用”。</p><p>点击“手动预览”，查看新文件名（如 doc_001.docx、doc_002.docx）。</p><p>确认后点击“执行重命名”。</p><p>可通过右键菜单删除不需要重命名的文件项。</p><p>结果：文件名中的 _temp_final 部分被移除。</p><hr><h3 id="📑-文件结构树示意" tabindex="-1">📑 文件结构树示意 <a class="header-anchor" href="#📑-文件结构树示意" aria-label="Permalink to &quot;📑 文件结构树示意&quot;">​</a></h3><p>输入或复制粘贴A文件夹路径到程序中，会自动将A文件夹下文件夹、文件名列出，启用相关选项，进行设置可以预览效果。</p><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p>注意：先测试备份原文件再批量使用</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250925102705175876722579750.jpg" alt=""></p><h3 id="📑-演示视频" tabindex="-1">📑 演示视频 <a class="header-anchor" href="#📑-演示视频" aria-label="Permalink to &quot;📑 演示视频&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1yQnszjEfC/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yQnszjEfC/</a></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统</p><p>注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-友情提示" tabindex="-1">📑 友情提示 <a class="header-anchor" href="#📑-友情提示" aria-label="Permalink to &quot;📑 友情提示&quot;">​</a></h3><p><strong>正式使用前请先测试/备份原文件，然后再大批量使用，以免造成不可逆损失。</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1650.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1650.html</a></p>',72)])])}const _=r(p,[["render",n]]);export{c as __pageData,_ as default};
